"use client";
import ConfirmDialog from "@/components/ConfirmDialog";
import ErrorState from "@/components/ErrorState";
import LoadingState from "@/components/LoadingState";
import PageHeader from "@/components/PageHeader";
import StatCard from "@/components/StatCard";
import StatusBadge from "@/components/StatusBadge";
import { Button } from "@/components/ui/button";
import {
Sidebar,
SidebarContent,
SidebarHeader,
SidebarMenu,
SidebarMenuButton,
SidebarMenuItem,
SidebarProvider,
SidebarTrigger,
useSidebar,
} from "@/components/ui/sidebar";
import {
Table,
TableBody,
TableCell,
TableHead,
TableHeader,
TableRow,
} from "@/components/ui/table";
import { useAuth } from "@/context/AuthContext";
import { useI18n } from "@/context/LocaleContext";
import { getPosts,request } from "@/lib/api";
import { Post } from "@/types";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect,useState } from "react";

import {
ClipboardList,
Search,
ShieldCheck,
Trash2,
Users,
} from "lucide-react";

function AdminNavigation({
  tab,
  onSelect,
}: {
  tab: string;
  onSelect: (value: string) => void;
}) {
  const { t, dir } = useI18n();

  const { setOpenMobile } = useSidebar();
  return (
    <Sidebar side={dir === "rtl" ? "right" : "left"} dir={dir} className="top-20 h-[calc(100svh-5rem)]">
      <SidebarHeader className="p-6">
        <ShieldCheck aria-hidden className="mb-2 size-7" />
        <p className="font-semibold">{t("admin.name")}</p>
        <p className="text-xs text-sidebar-foreground/70">
          {t("brand.name")}</p>
      </SidebarHeader>
      <SidebarContent className="px-3">
        <SidebarMenu>
          {[
            { id: "posts", label: t("search.allReports"), icon: ClipboardList },
            { id: "users", label: t("admin.users"), icon: Users },
          ].map((item) => (
            <SidebarMenuItem key={item.id}>
              <SidebarMenuButton
                isActive={tab === item.id}
                onPress={() => {
                  onSelect(item.id);
                  setOpenMobile(false);
                }}
              >
                <item.icon aria-hidden />
                <span>{item.label}</span>
              </SidebarMenuButton>
            </SidebarMenuItem>
          ))}
        </SidebarMenu>
      </SidebarContent>
    </Sidebar>
  );
}
interface AdminUser {
  id: string;
  email: string;
}

export default function AdminPage() {
  const { t, dir, number, date, college, errorText } = useI18n();

  const router = useRouter();
  const { user, token, isAdmin, loading: authLoading } = useAuth();
  const [posts, setPosts] = useState<Post[]>([]);
  const [users, setUsers] = useState<AdminUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [deletingId, setDeletingId] = useState<number | null>(null);
  const [deleting, setDeleting] = useState(false);
  const [search, setSearch] = useState("");

  useEffect(() => {
    if (!authLoading && (!user || !isAdmin)) {
      router.push("/");
    }
  }, [authLoading, user, isAdmin, router]);

  useEffect(() => {
    if (!user || !isAdmin || !token) return;

    Promise.all([
      getPosts(),
      request<AdminUser[]>("/admin/users", {
        headers: { Authorization: `Bearer ${token}` },
      }),
    ])
      .then(([allPosts, allUsers]) => {
        setPosts(allPosts);
        setUsers(allUsers);
      })
      .catch(() => setError(t("errors.admin")))
      .finally(() => setLoading(false));
  }, [user, isAdmin, token]);

  async function handleDelete(id: number) {
    if (!token) return;

    setDeleting(true);
    try {
      await request<void>(`/admin/posts/${id}`, {
        method: t("common.delete"),
        headers: { Authorization: `Bearer ${token}` },
      });
      setPosts((prev) => prev.filter((p) => p.id !== id));
      setDeleteDialogOpen(false);
    } catch (err) {
      setError(
        errorText(err, "errors.delete"),
      );
    } finally {
      setDeleting(false);
    }
  }

  const [tabValue, setTabValue] = useState("posts");

  if (authLoading || loading) {
    return (
      <div className="min-h-screen">
        <PageHeader title={t("admin.title")} />
        <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
          <LoadingState type="card" count={3} />
        </div>
      </div>
    );
  }

  if (!user || !isAdmin) {
    return null;
  }

  const visiblePosts = posts.filter((p) =>
    (p.title + " " + p.collegeName)
      .toLowerCase()
      .includes(search.toLowerCase()),
  );
  const visibleUsers = users.filter((u) =>
    (u.email + " " + u.id).toLowerCase().includes(search.toLowerCase()),
  );
  return (
    <SidebarProvider className="min-h-[calc(100svh-5rem)]">
      <AdminNavigation
        tab={tabValue}
        onSelect={(value) => {
          setTabValue(value);
          setSearch("");
        }}
      />
      <div className="min-w-0 flex-1 p-4 sm:p-8">
        <div className="mb-7 flex items-center gap-3">
          <SidebarTrigger />
          <div>
            <p className="text-xs font-semibold uppercase tracking-widest text-teal">
              {t("admin.community")}</p>
            <h1 className="text-2xl font-bold sm:text-3xl">{t("admin.title")}</h1>
          </div>
        </div>
        <div className="mb-8 grid gap-4 sm:grid-cols-2">
          <StatCard
            label={t("stats.total")}
            value={posts.length}
            icon="ClipboardList"
            description={t("admin.reportDescription")}
          />
          <StatCard
            label={t("admin.users")}
            value={users.length}
            icon="Users"
            tone="teal"
            description={t("admin.userDescription")}
          />
        </div>
        {error && <ErrorState message={error} />}
        <section className="rounded-2xl border bg-card shadow-sm">
          <div className="flex flex-wrap items-center justify-between gap-4 border-b p-5">
            <h2 className="text-lg font-semibold">
              {tabValue === "posts" ? t("search.allReports") : t("admin.users")}
            </h2>
            <div className="relative">
              <Search
                aria-hidden
                className="absolute start-3 top-3 size-4 text-muted-foreground"
              />
              <input
                aria-label={
                  tabValue === "posts" ? t("admin.searchReports") : t("admin.searchUsers")
                }
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder={t("admin.searchPlaceholder")}
                className="h-10 w-full rounded-lg border bg-background ps-9 pe-3 text-sm"
              />
            </div>
          </div>
          {tabValue === "posts" ? (
            <Table aria-label={t("browse.community")}>
              <TableHeader>
                <TableHead isRowHeader>{t("admin.report")}</TableHead>
                <TableHead>{t("admin.type")}</TableHead>
                <TableHead>{t("admin.college")}</TableHead>
                <TableHead>{t("report.reported")}</TableHead>
                <TableHead>{t("admin.actions")}</TableHead>
              </TableHeader>
              <TableBody renderEmptyState={() => t("empty.reports")}>
                {visiblePosts.map((post) => (
                  <TableRow key={post.id} id={post.id}>
                    <TableCell>
                      <Link
                        href={`/posts/${post.id}`}
                        className="block max-w-64 truncate font-medium hover:underline"
                      >
                        {post.title}
                      </Link>
                    </TableCell>
                    <TableCell>
                      <StatusBadge type={post.type} size="sm" />
                    </TableCell>
                    <TableCell>{college(post.collegeName)}</TableCell>
                    <TableCell>
                      {date(post.createdAt)}
                    </TableCell>
                    <TableCell>
                      <Button
                        variant="destructive"
                        size="sm"
                        aria-label={t("admin.deleteLabel", {title:post.title})}
                        onPress={() => {
                          setDeletingId(post.id);
                          setDeleteDialogOpen(true);
                        }}
                      >
                        <Trash2 aria-hidden className="size-4" />
                        {t("common.delete")}</Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          ) : (
            <Table aria-label={t("admin.registeredUsers")}>
              <TableHeader>
                <TableHead isRowHeader>{t("auth.email")}</TableHead>
                <TableHead>{t("admin.userId")}</TableHead>
              </TableHeader>
              <TableBody renderEmptyState={() => t("empty.users")}>
                {visibleUsers.map((u) => (
                  <TableRow id={u.id} key={u.id}>
                    <TableCell><bdi dir="ltr">{u.email}</bdi></TableCell>
                    <TableCell>{u.id}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </section>
      </div>
      <ConfirmDialog
        open={deleteDialogOpen}
        title={t("dialog.delete")}
        description={t("dialog.deleteDescription")}
        confirmLabel={t("common.delete")}
        isDestructive
        isLoading={deleting}
        onConfirm={() => {
          if (deletingId !== null) void handleDelete(deletingId);
        }}
        onCancel={() => {
          if (!deleting) {
            setDeleteDialogOpen(false);
            setDeletingId(null);
          }
        }}
      />
    </SidebarProvider>
  );
}

"use client";
import ConfirmDialog from "@/components/ConfirmDialog";
import EmptyState from "@/components/EmptyState";
import ErrorState from "@/components/ErrorState";
import LoadingState from "@/components/LoadingState";
import PageHeader from "@/components/PageHeader";
import StatusBadge from "@/components/StatusBadge";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { useAuth } from "@/context/AuthContext";
import { useI18n } from "@/context/LocaleContext";
import { deletePost,getMyPosts } from "@/lib/api";
import { Post } from "@/types";
import { Edit,Plus,Trash2 } from "lucide-react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect,useState } from "react";

export default function MyPostsPage() {
  const { t, number, date, college, errorText } = useI18n();

  const router = useRouter();
  const { user, token, loading: authLoading } = useAuth();
  const [posts, setPosts] = useState<Post[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [deletingId, setDeletingId] = useState<number | null>(null);
  const [deleting, setDeleting] = useState(false);

  useEffect(() => {
    if (!authLoading && !user) {
      router.push("/login");
    }
  }, [authLoading, user, router]);

  useEffect(() => {
    if (!user || !token) return;

    getMyPosts(token)
      .then(setPosts)
      .catch(() => setError(t("errors.mine")))
      .finally(() => setLoading(false));
  }, [user, token]);

  async function handleDelete(id: number) {
    if (!token) return;

    setDeleting(true);
    try {
      await deletePost(id, token);
      setPosts((prev) => prev.filter((p) => p.id !== id));
      setDeleteDialogOpen(false);
    } catch (err) {
      setError(
        errorText(err, "errors.delete"),
      );
    } finally {
      setDeleting(false);
    }
  }

  if (authLoading || loading) {
    return (
      <div className="min-h-screen">
        <PageHeader title={t("nav.mine")} />
        <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
          <LoadingState type="card" count={3} />
        </div>
      </div>
    );
  }

  if (!user) {
    return null;
  }

  return (
    <>
      <PageHeader
        title={t("nav.mine")}
        description={t("mine.description")}
        action={
          <Link
            href="/posts/new"
            className="inline-flex items-center justify-center rounded-lg bg-primary text-primary-foreground hover:bg-primary-hover active:bg-primary-active h-9 gap-1.5 px-2.5 text-sm font-medium whitespace-nowrap transition-all"
          >
            <Plus className="me-2 h-4 w-4" />
            {t("mine.new")}</Link>
        }
      />

      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8 sm:py-12">
        {error && <ErrorState message={error} />}

        {!error && posts.length === 0 && (
          <EmptyState
            icon={Plus}
            title={t("mine.empty")}
            description={t("mine.emptyDescription")}
            action={
              <Link
                href="/posts/new"
                className="inline-flex items-center justify-center rounded-lg bg-primary text-primary-foreground hover:bg-primary-hover active:bg-primary-active h-9 gap-1.5 px-2.5 text-sm font-medium whitespace-nowrap transition-all"
              >
                {t("nav.report")}</Link>
            }
          />
        )}

        {posts.length > 0 && (
          <div className="space-y-4">
            {posts.map((post) => (
              <Card
                key={post.id}
                className="overflow-hidden hover:shadow-md transition-shadow"
              >
                <div className="p-4 sm:p-6 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-2">
                      <StatusBadge type={post.type} size="sm" />
                      <span className="text-xs text-muted-foreground">
                        {date(post.createdAt)}
                      </span>
                    </div>
                    <Link
                      href={`/posts/${post.id}`}
                      className="font-semibold text-foreground hover:text-primary transition-colors truncate block mb-1"
                    >
                      {post.title}
                    </Link>
                    <p className="text-xs text-muted-foreground">
                      {college(post.collegeName)}
                    </p>
                  </div>

                  <div className="flex gap-2 shrink-0">
                    <Link
                      href={`/posts/${post.id}/edit`}
                      className="inline-flex items-center justify-center rounded-lg border-border bg-background text-foreground hover:bg-muted h-9 gap-1 px-2.5 text-xs font-medium whitespace-nowrap transition-all border"
                    >
                      <Edit className="h-4 w-4" />
                      <span className="ms-2">{t("common.edit")}</span>
                    </Link>
                    <Button
                      variant="destructive"
                      size="sm"
                      onClick={() => {
                        setDeletingId(post.id);
                        setDeleteDialogOpen(true);
                      }}
                    >
                      <Trash2 className="h-4 w-4" />
                      <span className="hidden sm:inline ms-2">{t("common.delete")}</span>
                    </Button>
                  </div>
                </div>
              </Card>
            ))}
          </div>
        )}
      </div>

      <ConfirmDialog
        open={deleteDialogOpen}
        title={t("dialog.delete")}
        description={t("dialog.deleteDescription")}
        confirmLabel={t("common.delete")}
        cancelLabel={t("common.cancel")}
        isDestructive
        isLoading={deleting}
        onConfirm={() => deletingId && handleDelete(deletingId)}
        onCancel={() => {
          setDeleteDialogOpen(false);
          setDeletingId(null);
        }}
      />
    </>
  );
}

"use client";
import ErrorState from "@/components/ErrorState";
import LoadingState from "@/components/LoadingState";
import PostForm from "@/components/PostForm";
import { useAuth } from "@/context/AuthContext";
import { useI18n } from "@/context/LocaleContext";
import { ApiError,getPostById,updatePost } from "@/lib/api";
import { CreatePostInput,Post } from "@/types";
import { useRouter } from "next/navigation";
import { useEffect,useState } from "react";

export default function EditPostPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { t, number } = useI18n();

  const router = useRouter();
  const { user, token, loading: authLoading } = useAuth();
  const [post, setPost] = useState<Post | null>(null);
  const [postId, setPostId] = useState<number | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!authLoading && !user) {
      router.push("/login");
    }
  }, [authLoading, user, router]);

  useEffect(() => {
    params.then(({ id }) => {
      const numId = Number(id);
      if (Number.isNaN(numId)) {
        setError(t("errors.invalidId"));
        setLoading(false);
        return;
      }
      setPostId(numId);
      getPostById(numId)
        .then(setPost)
        .catch(() => setError(t("errors.postNotFound")))
        .finally(() => setLoading(false));
    });
  }, [params]);

  if (authLoading || loading) {
    return (
      <div className="max-w-2xl mx-auto px-4 py-16">
        <LoadingState type="card" count={1} />
      </div>
    );
  }

  if (error || !post) {
    return (
      <div className="max-w-2xl mx-auto px-4 py-16">
        <ErrorState message={error || t("errors.postNotFound")} />
      </div>
    );
  }

  if (!user || post.userId !== user.sub) {
    return (
      <div className="max-w-2xl mx-auto px-4 py-16">
        <ErrorState title={t("errors.unauthorized")} message={t("errors.ownerOnly")} />
      </div>
    );
  }

  const initialValues: CreatePostInput = {
    title: post.title,
    description: post.description,
    type: post.type,
    collegeId: post.collegeId,
    contactNumber: post.contactNumber,
  };

  async function handleUpdate(values: CreatePostInput) {
    try {
      await updatePost(postId!, values, token!);
      router.push(`/posts/${postId}`);
    } catch (err) {
      throw err instanceof ApiError ? err : new Error(t("errors.update"));
    }
  }

  return (
    <>
      <div className="border-b border-border bg-background">
        <div className="max-w-2xl mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-8">
          <h1 className="text-3xl font-bold text-foreground mb-2">{t("form.edit")}</h1>
          <p className="text-muted-foreground">
            {t("form.editDescription")}</p>
        </div>
      </div>
      <div className="max-w-2xl mx-auto px-4 sm:px-6 lg:px-8 py-8 sm:py-12">
        <PostForm
          initialValues={initialValues}
          onSubmit={handleUpdate}
          submitLabel={t("common.save")}
        />
      </div>
    </>
  );
}

import PageContainer from "@/components/PageContainer";
import StatusBadge from "@/components/StatusBadge";
import { ApiError,getPostById } from "@/lib/api";
import { getI18n } from "@/lib/i18n/server";
import { ArrowLeft,CalendarDays,MapPin,Phone } from "lucide-react";
import Link from "next/link";
import { notFound } from "next/navigation";

export default async function PostDetailsPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { t, dir, number, date, college } = await getI18n();

  const { id } = await params;
  const postId = Number(id);

  if (Number.isNaN(postId)) {
    notFound();
  }

  let post;
  try {
    post = await getPostById(postId);
  } catch (err) {
    if (err instanceof ApiError && err.status === 404) {
      notFound();
    }
    throw err;
  }

  const formattedDate = date(post.createdAt, true);

  return (
    <PageContainer className="py-8 sm:py-12">
      <Link
        href={post.type === "Lost" ? "/lost" : "/found"}
        className="mb-7 inline-flex items-center gap-2 text-sm font-medium text-muted-foreground"
      >
        <ArrowLeft aria-hidden className="rtl:-scale-x-100 size-4" />
        {t(post.type === "Lost" ? "report.backLost" : "report.backFound")}
      </Link>
      <div className="grid items-start gap-6 lg:grid-cols-[minmax(0,1fr)_340px]">
        <article className="overflow-hidden rounded-2xl border bg-card shadow-sm">
          <div className="border-b bg-secondary/40 p-6 sm:p-8">
            <div className="mb-5 flex flex-wrap items-center justify-between gap-3">
              <StatusBadge type={post.type} />
              <span className="text-xs text-muted-foreground">
                {t("report.number",{id:post.id})}
              </span>
            </div>
            <h1 dir="auto" className="break-words text-3xl font-bold sm:text-4xl">
              {post.title}
            </h1>
            <p className="mt-4 flex items-center gap-2 text-sm text-muted-foreground">
              <MapPin aria-hidden className="size-4 shrink-0" />
              {college(post.collegeName)}
            </p>
          </div>
          <div className="p-6 sm:p-8">
            <h2 className="mb-3 text-lg font-semibold">{t("report.about")}</h2>
            <p dir="auto" className="whitespace-pre-wrap break-words leading-8 text-muted-foreground">
              {post.description}
            </p>
            <div className="mt-8 border-t pt-5 text-sm text-muted-foreground">
              <CalendarDays aria-hidden className="me-2 inline size-4" />
              {t("report.reported")} <time dateTime={post.createdAt}>{formattedDate}</time>
            </div>
          </div>
        </article>
        <aside className="space-y-5">
          <section className="rounded-2xl border bg-card p-6 shadow-sm">
            <span className="mb-4 inline-flex rounded-xl bg-teal-soft p-3 text-teal">
              <Phone aria-hidden className="size-5" />
            </span>
            <h2 className="text-xl font-semibold">
              {post.type === "Lost"
                ? t("report.seen")
                : t("report.yours")}
            </h2>
            <p className="my-3 text-sm text-muted-foreground">
              {t("report.contact")}</p>
            <a
              href={`tel:$<bdi dir="ltr">{post.contactNumber}</bdi>`}
              className="mt-5 flex items-center justify-center gap-2 rounded-xl bg-primary px-3 py-3 text-sm font-semibold text-white"
            >
              <Phone aria-hidden className="size-4" />
              {t("report.call")}{post.contactNumber}
            </a>
          </section>
          <section className="rounded-2xl border border-teal/20 bg-teal-soft p-6 text-teal">
            <h2 className="font-semibold">{t("report.handover")}</h2>
            <p className="mt-2 text-sm">
              {t("report.handoverDescription")}</p>
          </section>
        </aside>
      </div>
    </PageContainer>
  );
}

"use client";
import LocalizedForm from "@/components/LocalizedForm";
import { useI18n } from "@/context/LocaleContext";
import { getColleges } from "@/lib/api";
import { College,CreatePostInput,PostType } from "@/types";
import { useRouter } from "next/navigation";
import { useEffect,useState } from "react";

import { Alert,AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Card,CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
Select,
SelectContent,
SelectItem,
SelectTrigger,
SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";

interface PostFormProps {
  initialValues?: CreatePostInput;
  onSubmit: (values: CreatePostInput) => Promise<void>;
  submitLabel: string;
}

const emptyValues: CreatePostInput = {
  title: "",
  description: "",
  type: "Lost",
  collegeId: 0,
  contactNumber: "",
};

export default function PostForm({
  initialValues,
  onSubmit,
  submitLabel,
}: PostFormProps) {
  const { t, dir, college, translateMessage, errorText } = useI18n();

  const router = useRouter();
  const [colleges, setColleges] = useState<College[]>([]);
  const [values, setValues] = useState<CreatePostInput>(
    initialValues ?? emptyValues,
  );
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    getColleges()
      .then(setColleges)
      .catch(() => setError(t("errors.colleges")));
  }, []);

  function update<K extends keyof CreatePostInput>(
    key: K,
    value: CreatePostInput[K],
  ) {
    setValues((prev) => ({ ...prev, [key]: value }));
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);

    if (values.collegeId === 0) {
      setError(t("validation.college"));
      return;
    }

    setSubmitting(true);
    try {
      await onSubmit(values);
    } catch (err) {
      setError(errorText(err, "errors.generic"));
      setSubmitting(false);
    }
  }

  return (
    <Card className="rounded-2xl border shadow-sm">
      <CardContent className="p-6 sm:p-8">
        <div className="mb-7 border-b pb-5">
          <p className="text-xs font-semibold uppercase tracking-widest text-teal">
            {t("form.eyebrow")}</p>
          <h2 className="mt-2 text-xl font-semibold">{t("form.title")}</h2>
          <p className="mt-1 text-sm text-muted-foreground">
            {t("form.description")}</p>
        </div>
        <LocalizedForm onSubmit={handleSubmit} className="space-y-6">
          <div className="space-y-3">
            <p id="item-type-label" className="text-sm font-semibold">
              {t("report.type")}</p>
            <div
              role="group"
              aria-labelledby="item-type-label"
              className="grid grid-cols-2 gap-3"
            >
              {(["Lost", "Found"] as PostType[]).map((itemType) => (
                <Button
                  type="button"
                  key={itemType}
                  aria-pressed={values.type === itemType}
                  isDisabled={submitting}
                  variant={values.type === itemType ? "default" : "outline"}
                  onClick={() => update("type", itemType)}
                  className={
                    values.type === itemType
                      ? itemType === "Lost"
                        ? "h-16 rounded-xl border-orange bg-orange-soft text-orange hover:bg-orange-soft"
                        : "h-16 rounded-xl border-teal bg-teal-soft text-teal hover:bg-teal-soft"
                      : "h-16 rounded-xl"
                  }
                >
                  {itemType === "Lost" ? t("form.lost") : t("form.found")}
                </Button>
              ))}
            </div>
          </div>

          <div className="space-y-3">
            <Label htmlFor="title">{t("form.itemTitle")}</Label>
            <Input
              id="title"
              dir="auto"
              required
              maxLength={100}
              value={values.title}
              onChange={(e) => update("title", e.target.value)}
              placeholder={t("form.titlePlaceholder")}
              disabled={submitting}
            />
            <p className="text-xs text-muted-foreground">
              {t("form.counter",{count:values.title.length,max:100})}
            </p>
          </div>

          <div className="space-y-3">
            <Label htmlFor="description">{t("form.details")}</Label>
            <Textarea
              id="description"
              dir="auto"
              required
              maxLength={1000}
              rows={4}
              value={values.description}
              onChange={(e) => update("description", e.target.value)}
              placeholder={t("form.detailsPlaceholder")}
              disabled={submitting}
            />
            <p className="text-xs text-muted-foreground">
              {t("form.counter",{count:values.description.length,max:1000})}
            </p>
          </div>

          <div className="space-y-3">
            <Label htmlFor={"college"}>{t("form.college")}</Label>
            <Select
              aria-label={t("form.collegeLabel")}
              className="w-full"
              placeholder={t("form.selectCollege")}
              selectedKey={values.collegeId ? String(values.collegeId) : null}
              onSelectionChange={(key) => update("collegeId", Number(key))}
              isDisabled={submitting}
            >
              <SelectTrigger id={"college"} className="w-full">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {colleges.map((c) => (
                  <SelectItem key={c.id} id={String(c.id)}>
                    {college(c.name)}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-3">
            <Label htmlFor="contactNumber">{t("form.phone")}</Label>
            <Input
              id="contactNumber"
              dir="ltr"
              type="tel"
              autoComplete="tel"
              required
              value={values.contactNumber}
              onChange={(e) => update("contactNumber", e.target.value)}
              placeholder={t("form.phonePlaceholder")}
              pattern="^05\d{8}$"
              title={t("form.phoneHint")}
              disabled={submitting}
            />
            <p className="text-xs text-muted-foreground">
              {t("form.phonePublic")}</p>
          </div>

          {error && (
            <Alert variant="destructive" role="alert">
              <AlertDescription>{translateMessage(error)}</AlertDescription>
            </Alert>
          )}

          <div className="flex flex-col-reverse sm:flex-row gap-3 pt-4">
            <Button
              type="button"
              variant="outline"
              onClick={() => router.back()}
              isDisabled={submitting}
            >
              {t("common.cancel")}</Button>
            <Button type="submit" isDisabled={submitting} className="sm:flex-1">
              {submitting ? t("form.saving") : submitLabel}
            </Button>
          </div>
        </LocalizedForm>
      </CardContent>
    </Card>
  );
}

